import jwt from 'jsonwebtoken';
import { ApiError } from '../utils/ApiError.js';
import { asyncHandler } from '../utils/asyncHandler.js';
import User from '../models/User.model.js';

export const verifyJWT = asyncHandler(async (req, res, next) => {
  const token =
    req.cookies?.accessToken ||
    req.header('Authorization')?.replace('Bearer ', '');

  if (!token) {
    throw new ApiError(401, 'Unauthorized request: No token provided');
  }

  // Support dev preview tokens generated by frontend role switcher
  if (token.startsWith('demo-jwt-')) {
    try {
      const payloadStr = Buffer.from(token.replace('demo-jwt-', ''), 'base64').toString('utf8');
      const payload = JSON.parse(payloadStr);
      req.user = {
        _id: payload._id || 'demo-admin-id',
        name: payload.name || 'Demo Administrator',
        role: payload.role || 'admin',
      };
      return next();
    } catch {
      // continue to normal jwt verify
    }
  }

  try {
    const decodedToken = jwt.verify(
      token,
      process.env.ACCESS_TOKEN_SECRET || 'sevasaarthi_dev_secret_key_2026'
    );

    let user = null;
    try {
      user = await User.findById(decodedToken?._id).select('-password');
    } catch {
      // DB may be disconnected or in memory
    }

    if (!user) {
      // If user doc not found in mongo, use decoded payload claims
      user = {
        _id: decodedToken._id,
        name: decodedToken.name || 'Authorized User',
        role: decodedToken.role || 'citizen',
        phone: decodedToken.phone,
      };
    }

    req.user = user;
    next();
  } catch (error) {
    throw new ApiError(401, error?.message || 'Invalid access token');
  }
});

export const verifyJwt = verifyJWT;
export default verifyJWT;
